const thread = $json;
const messages = Array.isArray(thread.messages) ? thread.messages : [];
const me = [
  'luca@lucaberton.com',
  'luca@lucaberton.it',
  'luca@mrevolution.eu'
];

function clean(v) {
  return String(v || '').replace(/\s+/g, ' ').trim();
}
function bodyOf(m) {
  const candidates = [
    m.textPlain, m.text, m.snippet, m.html, m.textHtml,
    m.payload?.body?.data
  ];
  for (const c of candidates) {
    if (typeof c === 'string' && c.trim()) return clean(c).slice(0, 3500);
  }
  return '';
}

const compact = messages.slice(-12).map((m, i) => {
  const from = clean(m.From || m.from || '');
  const to = clean(m.To || m.to || '');
  const subject = clean(m.Subject || m.subject || '');
  const body = bodyOf(m);
  const fromMe = me.some(a => from.toLowerCase().includes(a));
  return {
    n: i + 1,
    id: m.id || '',
    date: m.Date || m.date || m.internalDate || '',
    from,
    to,
    subject,
    from_me: fromMe,
    text: body
  };
});

const subject = compact.find(m => m.subject)?.subject || '';
return [{
  json: {
    thread_id: thread.id || compact[0]?.threadId || '',
    subject,
    messages: compact,
    current_time: new Date().toISOString()
  }
}];

const src = $('Prepare thread').item.json;
const response = $json;

function getText(resp) {
  if (!resp) return '';
  // OpenAI-compatible shape (served by claude-bridge, not Anthropic's own API).
  if (resp.choices?.[0]?.message?.content) return resp.choices[0].message.content;
  if (Array.isArray(resp.content)) {
    for (const p of resp.content) if (typeof p?.text === 'string') return p.text;
  }
  if (typeof resp.output_text === 'string') return resp.output_text;
  return '';
}

const map = {
  '1 · Oggi': 'Label_6',
  '2 · Rispondere': 'Label_7',
  '3 · In attesa': 'Label_8',
  '4 · Follow-up': 'Label_9',
};

let out = { label: 'NONE', confidence: 0, reason: 'parse error' };
let skip = false;
try {
  const text = getText(response);
  const cleaned = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start < 0) throw new Error('No JSON object in model response');
  out = JSON.parse(cleaned.slice(start, end + 1));
} catch (e) {
  skip = true;
  out = { label: 'NONE', confidence: 0, reason: String(e?.message || e) };
}

const label = Object.prototype.hasOwnProperty.call(map, out.label) ? out.label : (out.label === 'NONE' ? 'NONE' : 'NONE');
const confidence = Number(out.confidence);
if (!Number.isFinite(confidence) || confidence < 0.65) skip = true;

return [{
  json: {
    thread_id: src.thread_id,
    subject: src.subject,
    target_label: label,
    target_label_id: map[label] || '',
    confidence: Number.isFinite(confidence) ? confidence : 0,
    reason: String(out.reason || ''),
    skip
  }
}];

const cls = $('Parse classification').item.json;
if (!cls.target_label_id) return [];
return [{ json: cls }];
